//! Frozen Unicode 15.0.0 Nd blocks, generated by scripts/generate-decimal-digits.py.
//! Historical oracle: CPython 3.12.10. Never use host Unicode versions for admission.
const ZERO_CODEPOINTS: &[u32] = &[
    0x30, 0x660, 0x6F0, 0x7C0, 0x966, 0x9E6, 0xA66, 0xAE6, 0xB66, 0xBE6, 0xC66, 0xCE6, 0xD66,
    0xDE6, 0xE50, 0xED0, 0xF20, 0x1040, 0x1090, 0x17E0, 0x1810, 0x1946, 0x19D0, 0x1A80, 0x1A90,
    0x1B50, 0x1BB0, 0x1C40, 0x1C50, 0xA620, 0xA8D0, 0xA900, 0xA9D0, 0xA9F0, 0xAA50, 0xABF0, 0xFF10,
    0x104A0, 0x10D30, 0x11066, 0x110F0, 0x11136, 0x111D0, 0x112F0, 0x11450, 0x114D0, 0x11650,
    0x116C0, 0x11730, 0x118E0, 0x11950, 0x11C50, 0x11D50, 0x11DA0, 0x11F50, 0x16A60, 0x16AC0,
    0x16B50, 0x1D7CE, 0x1D7D8, 0x1D7E2, 0x1D7EC, 0x1D7F6, 0x1E140, 0x1E2F0, 0x1E4F0, 0x1E950,
    0x1FBF0,
];

pub(super) fn normalize(text: &str) -> String {
    text.chars()
        .map(|ch| {
            let codepoint = ch as u32;
            let index = ZERO_CODEPOINTS.partition_point(|start| *start <= codepoint);
            let digit = index
                .checked_sub(1)
                .map(|index| codepoint - ZERO_CODEPOINTS[index]);
            match digit {
                Some(digit) if digit < 10 => (b'0' + digit as u8) as char,
                _ => ch,
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn all_frozen_digits_and_non_decimal_categories() {
        for start in ZERO_CODEPOINTS {
            let text: String = (0..10)
                .map(|offset| char::from_u32(start + offset).unwrap())
                .collect();
            assert_eq!(normalize(&text), "0123456789");
        }
        // Superscripts/fractions are numeric, but not decimal digits. Unicode
        // 16's Garay digits are intentionally absent from the historical table.
        assert_eq!(normalize("²½\u{10D40}"), "²½\u{10D40}");
    }
}
